<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Wooden Windmill</title>
  <style>
    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #c7dcd9;
      font-family: Georgia, "Times New Roman", serif;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    #title {
      position: fixed;
      top: 24px;
      left: 28px;
      z-index: 2;
      color: #34443a;
      pointer-events: none;
      user-select: none;
    }

    #title h1 {
      margin: 0;
      font-size: clamp(24px, 4vw, 42px);
