  </style>
</head>
<body>
  <div id="title">
    <h1>The Windmill</h1>
    <p>A turning lattice sail</p>
  </div>
  <div id="hint">Drag to orbit · Scroll to zoom · Double-click to reset</div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer, scene, camera, and lighting
    // -------------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xc7dcd9);
    scene.fog = new THREE.Fog(0xc7dcd9, 27, 68);

    const camera = new THREE.PerspectiveCamera(
      42,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    const hemisphere = new THREE.HemisphereLight(0xe6f3ef, 0x66563d, 1.8);
    scene.add(hemisphere);

    const sun = new THREE.DirectionalLight(0xffe6b8, 3.1);
    sun.position.set(9, 16, 11);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -13;
    sun.shadow.camera.right = 13;
    sun.shadow.camera.top = 17;
    sun.shadow.camera.bottom = -8;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 42;
    sun.shadow.bias = -0.00035;
    sun.shadow.normalBias = 0.025;
    scene.add(sun);

    const fill = new THREE.DirectionalLight(0x9fc7d0, 0.75);
    fill.position.set(-10, 8, -8);
    scene.add(fill);

    // -------------------------------------------------------------------------
    // Procedural textures
    // -------------------------------------------------------------------------

    function makeTexture(size, paint) {
      const canvas = document.createElement("canvas");
      canvas.width = size;
      canvas.height = size;
      const context = canvas.getContext("2d");
      paint(context, size);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping;
      texture.anisotropy = Math.min(
        8,
        renderer.capabilities.getMaxAnisotropy()
      );
      return texture;
    }

    const woodTexture = makeTexture(512, (ctx, size) => {
      ctx.fillStyle = "#80502f";
      ctx.fillRect(0, 0, size, size);

      for (let x = 0; x < size; x += 64) {
        const lightness = 34 + Math.random() * 15;
        ctx.fillStyle = `hsl(25, 48%, ${lightness}%)`;
        ctx.fillRect(x + 1, 0, 62, size);
        ctx.fillStyle = "rgba(38, 20, 10, 0.55)";
        ctx.fillRect(x, 0, 2, size);
      }

      for (let i = 0; i < 260; i++) {
        const x = Math.random() * size;
        const bend = (Math.random() - 0.5) * 24;
        ctx.strokeStyle = `rgba(48, 24, 11, ${0.035 + Math.random() * 0.09})`;
        ctx.lineWidth = 0.5 + Math.random() * 1.8;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.bezierCurveTo(
          x + bend,
          size * 0.3,
          x - bend,
          size * 0.7,
          x + (Math.random() - 0.5) * 12,
          size
        );
        ctx.stroke();
      }

      for (let i = 0; i < 18; i++) {
        const x = Math.random() * size;
        const y = Math.random() * size;
        ctx.strokeStyle = "rgba(45, 22, 10, 0.18)";
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.ellipse(x, y, 8 + Math.random() * 12, 18 + Math.random() * 28, 0, 0, Math.PI * 2);
        ctx.stroke();
      }
    });

    woodTexture.repeat.set(2, 1);

    const stoneTexture = makeTexture(512, (ctx, size) => {
      ctx.fillStyle = "#62625b";
      ctx.fillRect(0, 0, size, size);

      const rowHeight = 32;
      const blockWidth = 64;

      for (let row = 0; row < 16; row++) {
        const offset = row % 2 ? -blockWidth / 2 : 0;

        for (let x = offset; x < size; x += blockWidth) {
          const shade = 42 + Math.random() * 22;
          ctx.fillStyle = `hsl(35, 7%, ${shade}%)`;
          ctx.fillRect(x + 2, row * rowHeight + 2, blockWidth - 4, rowHeight - 4);
          ctx.strokeStyle = "rgba(25, 25, 22, 0.45)";
          ctx.strokeRect(x + 2, row * rowHeight + 2, blockWidth - 4, rowHeight - 4);
        }
      }
    });

    stoneTexture.repeat.set(2, 1);

    const grassTexture = makeTexture(512, (ctx, size) => {
      ctx.fillStyle = "#647b3d";
      ctx.fillRect(0, 0, size, size);

      for (let i = 0; i < 1800; i++) {
        const x = Math.random() * size;
        const y = Math.random() * size;
        const green = 65 + Math.random() * 55;
        ctx.strokeStyle = `rgba(${45 + green}, ${70 + green}, ${25 + green * 0.45}, 0.35)`;
        ctx.lineWidth = 0.5 + Math.random();
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + (Math.random() - 0.5) * 4, y - 2 - Math.random() * 5);
        ctx.stroke();
      }
    });

    grassTexture.repeat.set(4, 2);

    const materials = {
      wood: new THREE.MeshStandardMaterial({
        map: woodTexture,
        color: 0xffffff,
        roughness: 0.82
      }),
      darkWood: new THREE.MeshStandardMaterial({
        map: woodTexture,
        color: 0x9a6740,
        roughness: 0.88
      }),
      lightWood: new THREE.MeshStandardMaterial({
        map: woodTexture,
        color: 0xe0ad72,
        roughness: 0.76
      }),
      stone: new THREE.MeshStandardMaterial({
        map: stoneTexture,
        color: 0xb4b0a5,
        roughness: 1
      }),
      grass: new THREE.MeshStandardMaterial({
        map: grassTexture,
        color: 0x91a564,
        roughness: 1
      }),
      glass: new THREE.MeshStandardMaterial({
        color: 0x263e3b,
        roughness: 0.24,
        metalness: 0.05,
        emissive: 0x6b3512,
        emissiveIntensity: 0.35
      }),
      shutter: new THREE.MeshStandardMaterial({
        color: 0x354b3d,
        roughness: 0.86
      }),
      metal: new THREE.MeshStandardMaterial({
        color: 0x393630,
        roughness: 0.55,
        metalness: 0.45
      })
    };

    // -------------------------------------------------------------------------
    // Geometry helpers
    // -------------------------------------------------------------------------

    function addBox(
      width,
      height,
      depth,
      material,
      x,
      y,
      z,
      parent = scene
    ) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(width, height, depth),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addCylinder(
      radiusTop,
      radiusBottom,
      height,
      material,
      x,
      y,
      z,
      segments = 24,
      parent = scene
    ) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(
          radiusTop,
          radiusBottom,
          height,
          segments
        ),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function cylinderBetween(start, end, radius, material, parent = scene) {
      const direction = end.clone().sub(start);
      const length = direction.length();

      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radius, radius, length, 8),
        material
      );

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // -------------------------------------------------------------------------
    // Grassy mound and surrounding landscape
    // -------------------------------------------------------------------------

    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(90, 90),
      materials.grass
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.62;
    ground.receiveShadow = true;
    scene.add(ground);

    const mound = new THREE.Mesh(
      new THREE.SphereGeometry(4, 64, 32),
      materials.grass
    );
    mound.scale.set(1.38, 0.65, 1.38);
    mound.position.y = 0.03;
    mound.castShadow = true;
    mound.receiveShadow = true;
    scene.add(mound);

    const hillMaterial = new THREE.MeshStandardMaterial({
      color: 0x71865b,
      roughness: 1
    });

    [
      [-12, -0.8, -8, 10, 2.1, 6],
      [14, -1.0, -12, 13, 2.8, 7],
      [-17, -1.1, 7, 11, 2.4, 6]
    ].forEach(([x, y, z, sx, sy, sz]) => {
      const hill = new THREE.Mesh(
        new THREE.SphereGeometry(1, 32, 18),
        hillMaterial
      );
      hill.position.set(x, y, z);
      hill.scale.set(sx, sy, sz);
      hill.receiveShadow = true;
      scene.add(hill);
    });

    // Soft, low-poly clouds.
    const cloudMaterial = new THREE.MeshLambertMaterial({
      color: 0xf4f0df,
      transparent: true,
      opacity: 0.82,
      depthWrite: false
    });

    function addCloud(x, y, z, scale) {
      const cloud = new THREE.Group();
      cloud.position.set(x, y, z);
      cloud.scale.setScalar(scale);

      [
        [-1.1, 0, 0, 0.85],
        [-0.35, 0.25, 0, 1.1],
        [0.55, 0.12, 0, 0.95],
        [1.2, -0.04, 0, 0.72]
      ].forEach(([cx, cy, cz, radius]) => {
        const puff = new THREE.Mesh(
          new THREE.SphereGeometry(radius, 16, 10),
          cloudMaterial
        );
        puff.position.set(cx, cy, cz);
        puff.scale.y = 0.65;
        cloud.add(puff);
      });

      scene.add(cloud);
    }

    addCloud(-10, 14.5, -15, 1.6);
    addCloud(12, 16, -20, 1.25);
    addCloud(20, 12, -8, 1.0);

    // -------------------------------------------------------------------------
    // Stone base
    // -------------------------------------------------------------------------

    addCylinder(2.05, 2.15, 0.36, materials.stone, 0, 0.18, 0, 40);
    addCylinder(1.78, 1.9, 0.46, materials.stone, 0, 0.58, 0, 40);
    addCylinder(1.68, 1.72, 0.18, materials.darkWood, 0, 0.91, 0, 40);

    // Scattered stones around the base.
    const rockGeometry = new THREE.DodecahedronGeometry(1, 0);
    const rockMaterial = new THREE.MeshStandardMaterial({
      color: 0x777870,
      roughness: 1
    });

    for (let i = 0; i < 22; i++) {
      const angle = Math.random() * Math.PI * 2;
      const distance = 2.65 + Math.random() * 3.4;
      const scale = 0.14 + Math.random() * 0.34;

      const rock = new THREE.Mesh(rockGeometry, rockMaterial);
      rock.position.set(
        Math.cos(angle) * distance,
        0.58 + scale * 0.22,
        Math.sin(angle) * distance
      );
      rock.scale.set(
        scale * (0.8 + Math.random() * 0.6),
        scale * (0.55 + Math.random() * 0.35),
        scale * (0.8 + Math.random() * 0.6)
      );
      rock.rotation.set(
        Math.random() * Math.PI,
        Math.random() * Math.PI,
        Math.random() * Math.PI
      );
      rock.castShadow = true;
      rock.receiveShadow = true;
      scene.add(rock);
    }

    // -------------------------------------------------------------------------
    // Tapered wooden tower
    // -------------------------------------------------------------------------

    const tower = addCylinder(
      1.12,
      1.65,
      6.6,
      materials.wood,
      0,
      4.3,
      0,
      40
    );

    addCylinder(1.69, 1.69, 0.09, materials.darkWood, 0, 3.05, 0, 40);
    addCylinder(1.18, 1.18, 0.12, materials.darkWood, 0, 7.57, 0, 40);

    // -------------------------------------------------------------------------
    // Door and two windows
    // -------------------------------------------------------------------------

    function frontRadius(y) {
      return 1.65 - ((y - 1) / 6.6) * 0.53;
    }

    function addDoor() {
      const group = new THREE.Group();
      const z = frontRadius(2.08) + 0.045;
      group.position.set(0, 0, z);
      scene.add(group);

      addBox(1.08, 1.88, 0.12, materials.darkWood, 0, 2.08, 0, group);

      for (let i = 0; i < 6; i++) {
        addBox(
          0.96,
          0.245,
          0.025,
          materials.lightWood,
          0,
          1.36 + i * 0.295,
          0.074,
          group
        );
      }

      addBox(0.13, 2.12, 0.18, materials.darkWood, -0.57, 2.08, 0.14, group);
      addBox(0.13, 2.12, 0.18, materials.darkWood, 0.57, 2.08, 0.14, group);
      addBox(1.27, 0.14, 0.18, materials.darkWood, 0, 3.14, 0.14, group);
      addBox(1.27, 0.14, 0.18, materials.darkWood, 0, 1.02, 0.14, group);

      cylinderBetween(
        new THREE.Vector3(-0.42, 1.35, 0.19),
        new THREE.Vector3(0.42, 2.82, 0.19),
        0.045,
        materials.lightWood,
        group
      );

      const handle = new THREE.Mesh(
        new THREE.SphereGeometry(0.055, 12, 8),
        materials.metal
      );
      handle.position.set(0.38, 2.12, 0.235);
      handle.castShadow = true;
      group.add(handle);

      addBox(1.2, 0.12, 0.3, materials.stone, 0, 1.0, 0.1, group);
    }

    function addWindow(y, scale = 1) {
      const group = new THREE.Group();
      const z = frontRadius(y) + 0.05;
      group.position.set(0, y, z);
      group.scale.setScalar(scale);
      scene.add(group);

      addBox(0.94, 0.74, 0.12, materials.darkWood, 0, 0, 0, group);
      addBox(0.74, 0.54, 0.08, materials.glass, 0, 0, 0.075, group);

      addBox(0.24, 0.74, 0.08, materials.shutter, -0.52, 0, 0.1, group);
      addBox(0.24, 0.74, 0.08, materials.shutter, 0.52, 0, 0.1, group);

      addBox(0.055, 0.58, 0.06, materials.lightWood, 0, 0, 0.16, group);
      addBox(0.69, 0.055, 0.06, materials.lightWood, 0, 0, 0.16, group);
      addBox(0.98, 0.08, 0.22, materials.stone, 0, -0.4, 0.04, group);
    }

    addDoor();
    addWindow(4.28, 0.94);
    addWindow(5.43, 0.86);

    // -------------------------------------------------------------------------
    // Horizontal shaft, conical cap, and four rotating lattice sails
    // -------------------------------------------------------------------------

    const rotatingHub = new THREE.Group();
    rotatingHub.position.y = 9.25;
    scene.add(rotatingHub);

    const shaft = addCylinder(
      0.105,
      0.105,
      4.45,
      materials.metal,
      0,
      0,
      0,
      20,
      rotatingHub
    );
    shaft.rotation.z = Math.PI / 2;

    // Bearing blocks on either side of the cap.
    addBox(0.24, 0.38, 0.56, materials.darkWood, -1.43, 9.25, 0);
    addBox(0.24, 0.38, 0.56, materials.darkWood, 1.43, 9.25, 0);

    const cap = new THREE.Mesh(
      new THREE.ConeGeometry(1.2, 2.25, 32),
      materials.darkWood
    );
    cap.position.y = 8.725;
    cap.castShadow = true;
    cap.receiveShadow = true;
    scene.add(cap);

    addCylinder(0.12, 0.16, 0.28, materials.lightWood, 0, 10.08, 0, 16);
    const finial = new THREE.Mesh(
      new THREE.SphereGeometry(0.13, 16, 10),
      materials.lightWood
    );
    finial.position.y = 10.27;
    finial.castShadow = true;
    scene.add(finial);

    function createSail(index) {
      const group = new THREE.Group();
      group.rotation.x = index * Math.PI / 2;
      rotatingHub.add(group);

      // The outline of a tapered windmill blade.
      const outline = [
        [-0.20, 0.00],
        [ 0.20, 0.00],
        [ 0.70, 0.45],
        [ 0.88, 1.60],
        [ 0.72, 3.25],
        [ 0.42, 4.05],
        [ 0.20, 4.15],
        [ 0.08, 3.90],
        [-0.20, 4.15],
        [-0.42, 4.05],
        [-0.72, 3.25],
        [-0.88, 1.60],
        [-0.70, 0.45]
      ];

      // Perimeter frame.
      for (let i = 0; i < outline.length; i++) {
        const a = new THREE.Vector3(outline[i][0], outline[i][1], 0);
        const b = new THREE.Vector3(outline[(i + 1) % outline.length][0],
          outline[(i + 1) % outline.length][1], 0);
        cylinderBetween(a, b, 0.035, materials.lightWood, group);
      }

      // Central spar.
      cylinderBetween(
        new THREE.Vector3(0, 0.18, 0),
        new THREE.Vector3(0, 4.10, 0),
        0.052,
        materials.lightWood,
        group
      );

      // Tapered crossbars.
      const crossbars = [
        [0.82, 0.48],
        [0.70, 0.95],
        [0.76, 1.60],
        [0.70, 2.30],
        [0.55, 3.00],
        [0.30, 3.72],
        [0.16, 4.05]
      ];

      crossbars.forEach(([width, y], i) => {
        addBox(width, 0.055, 0.075, materials.wood, 0, y, 0, group);

        const half = width / 2;
        cylinderBetween(
          new THREE.Vector3(0, y - 0.12, 0),
          new THREE.Vector3(-half, y, 0),
          0.022,
          materials.lightWood,
          group
        );
        cylinderBetween(
          new THREE.Vector3(0, y - 0.12, 0),
          new THREE.Vector3(half, y, 0),
          0.022,
          materials.lightWood,
          group
        );
      });

      // Longitudinal diagonal braces.
      cylinderBetween(
        new THREE.Vector3(-0.17, 0.42, 0),
        new THREE.Vector3(-0.66, 3.83, 0),
        0.022,
        materials.lightWood,
        group
      );
      cylinderBetween(
        new THREE.Vector3(0.17, 0.42, 0),
        new THREE.Vector3(0.66, 3.83, 0),
        0.022,
        materials.lightWood,
        group
      );

      // Hub and its two end caps.
      const hub = addCylinder(
        0.29,
        0.29,
        0.62,
        materials.darkWood,
        0,
        0,
        0,
        24,
        group
      );
      hub.rotation.z = Math.PI / 2;

      for (const x of [-0.325, 0.325]) {
        const capDisc = addCylinder(
          0.31,
          0.31,
          0.055,
          materials.lightWood,
          x,
          0,
          0,
          24,
          group
        );
        capDisc.rotation.z = Math.PI / 2;
      }
    }

    createSail(0);
    createSail(1);
    createSail(2);
    createSail(3);

    // -------------------------------------------------------------------------
    // Instanced grass tufts
    // -------------------------------------------------------------------------

    const grassTuftGeometry = new THREE.ConeGeometry(0.035, 0.24, 3);
    grassTuftGeometry.translate(0, 0.12, 0);

    const grassTuftMaterial = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 1
    });

    const tuftCount = 260;
    const grassTufts = new THREE.InstancedMesh(
      grassTuftGeometry,
      grassTuftMaterial,
      tuftCount
    );

    const dummy = new THREE.Object3D();
    const tuftColor = new THREE.Color();

    for (let i = 0; i < tuftCount; i++) {
      let x;
      let z;
      let attempts = 0;

      do {
        x = (Math.random() - 0.5) * 16;
        z = (Math.random() - 0.5) * 16;
        attempts++;
      } while (
        attempts < 20 &&
        (x * x + z * z < 5.4 ||
         Math.abs(x) < 2.4 && Math.abs(z) < 2.4)
      );

      const height = 0.65 + Math.random() * 0.22;
      dummy.position.set(x, height, z);
      dummy.rotation.set(
        (Math.random() - 0.5) * 0.12,
        Math.random() * Math.PI,
        (Math.random() - 0.5) * 0.12
      );
      dummy.scale.set(
        0.7 + Math.random() * 0.8,
        0.55 + Math.random() * 0.7,
        0.7 + Math.random() * 0.8
      );
      dummy.updateMatrix();

      grassTufts.setMatrixAt(i, dummy.matrix);
      tuftColor.setHSL(
        0.22 + Math.random() * 0.05,
        0.34 + Math.random() * 0.16,
        0.34 + Math.random() * 0.13
      );
      grassTufts.setColorAt(i, tuftColor);
    }

    grassTufts.instanceMatrix.needsUpdate = true;
    grassTufts.instanceColor.needsUpdate = true;
    grassTufts.receiveShadow = true;
    scene.add(grassTufts);

    // -------------------------------------------------------------------------
    // Custom orbit controls: pointer drag, wheel zoom, double-click reset
    // -------------------------------------------------------------------------

    const target = new THREE.Vector3(0, 6.1, 0);
    const spherical = new THREE.Spherical(16, 1.32, 0.58);
    const initialSpherical = spherical.clone();

    function updateCamera() {
      camera.position.setFromSpherical(spherical).add(target);
      camera.lookAt(target);
    }

    let dragging = false;
    let previousX = 0;
    let previousY = 0;

    renderer.domElement.addEventListener("pointerdown", (event) => {
      dragging = true;
      previousX = event.clientX;
      previousY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const deltaX = event.clientX - previousX;
      const deltaY = event.clientY - previousY;
      previousX = event.clientX;
      previousY = event.clientY;

      spherical.theta -= deltaX * 0.006;
      spherical.phi = THREE.MathUtils.clamp(
        spherical.phi - deltaY * 0.005,
        0.35,
        1.52
      );

      updateCamera();
    });

    function endDrag(event) {
      dragging = false;
      if (renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", endDrag);
    renderer.domElement.addEventListener("pointercancel", endDrag);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        spherical.radius = THREE.MathUtils.clamp(
          spherical.radius * Math.exp(event.deltaY * 0.001),
          9,
          28
        );
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", () => {
      spherical.copy(initialSpherical);
      updateCamera();
    });

    window.addEventListener("keydown", (event) => {
      if (event.key === "ArrowLeft") spherical.theta += 0.08;
      if (event.key === "ArrowRight") spherical.theta -= 0.08;
      if (event.key === "ArrowUp") spherical.phi = Math.max(0.35, spherical.phi - 0.06);
      if (event.key === "ArrowDown") spherical.phi = Math.min(1.52, spherical.phi + 0.06);
      if (event.key === "+" || event.key === "=") spherical.radius = Math.max(9, spherical.radius - 0.5);
      if (event.key === "-") spherical.radius = Math.min(28, spherical.radius + 0.5);
      updateCamera();
    });

    updateCamera();

    // -------------------------------------------------------------------------
    // Animation
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();

    function animate() {
      const elapsed = clock.getElapsedTime();

      // The four sails turn together around the horizontal X shaft.
      rotatingHub.rotation.x = elapsed * 0.18;

      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    animate();

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
